        write_u32(mutex + MUTEX_OWNER, thread as u32);
        write_u32(mutex + MUTEX_COUNT, read_u32(mutex + MUTEX_COUNT) + 1);
        let tail = read_u32(thread + THREAD_MUTEX_TAIL) as usize;
