/// inferred: OSWaitCond`.
///
/// # Arguments
/// - `condition`: wait-queue object signalled by the producer.
/// - `mutex`: mutex currently owned by the calling thread.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Releases and re-acquires `mutex`; blocks until another thread wakes the
/// condition queue.
///
/// # Safety
/// The calling thread must own `mutex` and `condition` must be a valid
/// `{head, tail}` pair.
///
/// # Confidence
/// high - the release/sleep/re-lock sequence is unambiguous.
pub unsafe fn wait_condition(condition: usize, mutex: usize) {
    let was_enabled = disable_interrupts();
    let thread = current_thread();
    if read_u32(mutex + MUTEX_OWNER) == thread as u32 {
        let next = read_u32(mutex + MUTEX_NEXT) as usize;
        let count = read_u32(mutex + MUTEX_COUNT);
        let prev = read_u32(mutex + MUTEX_PREV) as usize;
        write_u32(mutex + MUTEX_COUNT, 0);
        if next == 0 {
            write_u32(thread + THREAD_MUTEX_TAIL, prev as u32);
        } else {
            write_u32(next + MUTEX_PREV, prev as u32);
        }
        if prev == 0 {
            write_u32(thread + THREAD_MUTEX_HEAD, next as u32);
        } else {
            write_u32(prev + MUTEX_NEXT, next as u32);
        }
        write_u32(mutex + MUTEX_OWNER, 0);
        if read_i32(thread + THREAD_PRIORITY) < read_i32(thread + THREAD_BASE_PRIORITY) {
            let priority = priority_from_mutexes(thread);
            write_u32(thread + THREAD_PRIORITY, priority as u32);
        }
        scheduler_lock();
        wake_all(mutex + MUTEX_QUEUE);
        scheduler_unlock();
        sleep_thread(condition);
        lock_mutex(mutex);
        write_u32(mutex + MUTEX_COUNT, count);
    }
    restore_interrupts(was_enabled);
}

