/// Enables the locked L1 cache and clears/zeros both locked regions.
///
/// # Original
/// - Ghidra: `FUN_801ac5d0` at `0x801ac5d0` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ac5d0_FUN_801ac5d0.c`; the raw
///   words at `0x801ac5d0` set `HID2 |= 0x1000`, run 0x400 `dcbt`/`dcbst`
///   pairs over `0x80000000`, set `HID2 |= 0x100f`, write SPRs 1023/1022,
///   and run 0x200 `dcbz_l` blocks over `0xE0000000`.
/// - Role: `
/// inferred: LCEnable`-style locked-cache bring-up.
///
/// # Arguments
/// None.
///
/// # Returns
/// The `r3:r4` pair the original leaves behind: `r3` is the end address
/// `0xE0004000`, `r4` is `HID2 | 0x100f`. Callers in this image ignore it.
///
/// # Side effects
/// Programs HID2, touches the normal-cache and locked-cache windows, and
/// writes the two unidentified SPRs 1023/1022.
///
/// # Safety
/// Privileged cache/SPR operations; must run with interrupts masked on the
/// target.
///
/// # Confidence
/// medium - the loops and HID2 bits are read from the bytes, but SPRs 1022
/// and 1023 have no recovered name.
pub unsafe fn lc_enable() -> u64 {
    let mut hid2 = get_hid2();
    set_hid2(hid2 | 0x1000);
    let mut addr = 0x8000_0000usize;
    for _ in 0..0x400 {
        dcbt(addr);
        dcbst(addr);
        addr = addr.wrapping_add(0x20);
    }
    hid2 = get_hid2();
    set_hid2(hid2 | 0x100f);
// unknown: SPR 1023 / 1022 select the locked-cache DMA windows; the DOL
// gives no symbol and the values are the two constants loaded here.
    write_unidentified_spr(1023, 0xe000_0002);
    write_unidentified_spr(1022, 0xe000_01fe);
    isync();
    let mut locked = 0xe000_0000usize;
    for _ in 0..0x200 {
        dcbz_l(locked);
        locked = locked.wrapping_add(0x20);
    }
    ((0xe000_4000u64) << 32) | ((hid2 | 0x100f) as u64)
}

/// Runs [`lc_enable`] with interrupts masked.
///
/// # Original
/// - Ghidra: `FUN_801ac6a0` at `0x801ac6a0` (56 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ac6a0_FUN_801ac6a0.c`: `bl
///   0x801b1140`, `bl 0x801ac5d0`, restore via `0x801b1180`.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// Privileged cache/SPR operations; the wrapper restores the caller's
/// interrupt state.
///
/// # Confidence
/// high for the wrapper; see [`lc_enable`] for the inner confidence.
pub unsafe fn lc_enable_locked() {
    let was_enabled = disable_interrupts();
    lc_enable();
    restore_interrupts(was_enabled);
}

/// Invalidates the locked L1 cache and clears the HID2 locked-cache bits.
///
/// # Original
/// - Ghidra: `FUN_801ac6e0` at `0x801ac6e0` (40 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ac6e0_FUN_801ac6e0.c`; raw
///   words show a 0x200-iteration `dcbi` loop over `0xE0000000`, then
///   `mfspr r4,920`, `rlwinm r4,r4,0,4,31`, `mtspr 920,r4`.
/// - Role: `
/// inferred: LCDisable`-style locked-cache teardown.
///
/// # Arguments
/// None.
///
/// # Returns
/// The `r3:r4` pair the original leaves behind: `r3` is `0xE0004000`, `r4` is
/// `HID2 & 0x0fffffff`. Callers ignore it.
///
/// # Side effects
/// Invalidates the locked cache window and clears HID2 bits 28-31.
///
/// # Safety
/// Privileged cache/SPR operations.
///
/// # Confidence
/// medium - the loop and HID2 mask are read from the bytes; the return pair is
/// a register-pair artifact, not a C value.
pub unsafe fn lc_disable() -> u64 {
    let mut addr = 0xe000_0000usize;
    for _ in 0..0x200 {
        dcbi(addr);
        addr = addr.wrapping_add(0x20);
    }
    let hid2 = get_hid2();
    set_hid2(hid2 & 0x0fff_ffff);
    ((0xe000_4000u64) << 32) | ((hid2 & 0x0fff_ffff) as u64)
}

// ---------------------------------------------------------------------------
// Saved-context installation and thread-system startup

// ---------------------------------------------------------------------------
/// Address of the context installed as the live exception context.
const CURRENT_CONTEXT: usize = 0x8000_00d8;
/// Address of the context most recently installed (the original's `d4` word).
const LAST_CONTEXT: usize = 0x8000_00d4;
/// Current-context pointer used by the exception entry (the original's `c0`).
const LIVE_CONTEXT: usize = 0x8000_00c0;
/// The static context at `0x8038e938` used by the boot thread and the idle loop.
const SYSTEM_CONTEXT: usize = 0x8038_e938;
/// High word of the OS time base cache (`0x800030d8`).
const OS_TIME_HIGH: usize = 0x8000_30d8;
/// Low word of the OS time base cache (`0x800030dc`).
const OS_TIME_LOW: usize = 0x8000_30dc;
/// Switch-handler pointer called with `(previous_thread, next_context)`.
const SWITCH_HANDLER_OFFSET: isize = -0x6150;
/// Installs `context` as the live exception context.
///
/// # Original
/// - Ghidra: `FUN_801acd40` at `0x801acd40` (92 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801acd40_FUN_801acd40.c`: stores
///   `context & 0x3fffffff` at `0x800000c0`, stores `context` at `0x800000d4`,
///   then sets or clears bit `0x2000` in `context + 0x19c` depending on
///   whether it matches the current context at `0x800000d8`. The clear path
///   ends with `isync`.
/// - Role: `
/// inferred: __OSLoadContext` / current-context publication.
///
/// # Arguments
/// - `context`: saved-context block. `+0x19c` is the saved MSR.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Updates three absolute low-memory words and one context status word.
///
/// # Safety
/// `context` must point to a readable/writable saved-context block; the
/// exception vectors treat the published pointer as live.
///
/// # Confidence
/// high - three independent callers and the exact bit test are visible.
pub unsafe fn install_context(context: usize) {
    write_u32(LIVE_CONTEXT, (context as u32) & 0x3fff_ffff);
    write_u32(LAST_CONTEXT, context as u32);
    if read_u32(CURRENT_CONTEXT) as usize == context {
        write_u32(context + 0x19c, read_u32(context + 0x19c) | 0x2000);
        return;
    }
    write_u32(context + 0x19c, read_u32(context + 0x19c) & !0x2000);
    isync();
}

/// Clears the two exception-state halfwords in a saved context.
///
/// # Original
/// - Ghidra: `FUN_801acf80` at `0x801acf80` (36 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801acf80_FUN_801acf80.c`: zeroes
///   `context + 0x1a0` and `context + 0x1a2`, and if the context is the one at
///   `0x800000d8`, clears that global.
/// - Role: `
/// inferred: __OSClearContext`.
///
/// # Arguments
/// - `context`: saved-context block.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// `context` must be writable.
///
/// # Confidence
/// high.
pub unsafe fn clear_context(context: usize) {
    write_u16(context + 0x1a0, 0);
    write_u16(context + 0x1a2, 0);
    if read_u32(CURRENT_CONTEXT) as usize == context {
        write_u32(CURRENT_CONTEXT, 0);
    }
}

/// Builds the initial saved-register image for a new thread.
///
/// # Original
/// - Ghidra: `FUN_801acfb0` at `0x801acfb0` (188 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801acfb0_FUN_801acfb0.c`: stores
///   `entry` at `+0x198` (LR), `stack` at `+0x04` (SP), `0x9032` at `+0x19c`
///   (MSR), the SDA2/SDA bases at `+0x08`/`+0x34`, zeroes CR/XER, the GPR
///   slots `+0x0c`..`+0x30` and `+0x38`..`+0x7c`, the GQR slots
///   `+0x1a8`..`+0x1c0`, and calls [`clear_context`].
/// - Role: `
/// inferred: __OSInitContext`.
///
/// # Arguments
/// - `context`: context block to fill.
/// - `entry`: initial program counter written to the LR slot.
/// - `stack`: initial stack pointer written to the SP slot.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Overwrites the context's register image; observable on the first switch.
///
/// # Safety
/// `context` must point to a writable 0x1c4-byte context block.
///
/// # Confidence
/// high - every offset is explicit in the decompiled body and the raw bytes
/// agree on the LR/SP/MSR constants.
pub unsafe fn init_context(context: usize, entry: u32, stack: u32) {
    write_u32(context + 0x198, entry);
    write_u32(context + 0x04, stack);
    write_u32(context + 0x19c, 0x9032);
    write_u32(context + 0x80, 0);
    write_u32(context + 0x8c, 0);
    write_u32(context + 0x08, SDA2_BASE as u32);
    write_u32(context + 0x34, SDA_BASE as u32);
    for offset in [0x0c, 0x10, 0x14, 0x18, 0x1c, 0x20, 0x24, 0x28, 0x2c, 0x30, ] {
        write_u32(context + offset, 0);
    }
    for offset in [0x38, 0x3c, 0x40, 0x44, 0x48, 0x4c, 0x50, 0x54, 0x58, 0x5c, 0x60, 0x64, 0x68,
        0x6c, 0x70, 0x74, 0x78, 0x7c, ] {
        write_u32(context + offset, 0);
    }
    write_u32(context + 0x1a4, 0);
    for offset in [0x1a8, 0x1ac, 0x1b0, 0x1b4, 0x1b8, 0x1bc, 0x1c0] {
        write_u32(context + offset, 0);
    }
    clear_context(context);
}

/// Initialises the OS thread system, run-queue table and idle context.
///
/// # Original
/// - Ghidra: `FUN_801b4890` at `0x801b4890` (640 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801b4890_FUN_801b4890.c` and the
///   raw words at `0x801b4890`: writes the system context at `0x8038e938`,
///   publishes it via `0x801acf80`/`0x801acd40`, stores the initial stack
///   (`0x8043fc40`/`0x8042fc3c`) and the `0xdeadbabe` guard, calls the switch
///   handler, sets `0x800000e4`, zeroes the stack above the guard, clears the
///   run-queue table (`0x8038ec50`, 0x100 bytes) and the scheduler counters,
///   and finally initialises the idle context at `0x8038ed50`.
/// - Role: `
/// inferred: __OSInitThread`.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Replaces the current-thread pointer, clears all run queues and the
/// scheduler lock, and zeroes the boot stack above `0x8042fc40`.
///
/// # Safety
/// One-time boot path; must not run while any thread is live. The zeroing loop
/// writes the range `0x8042fc40..stack_pointer`, which the boot stack owns.
///
/// # Confidence
/// high - the raw instruction stream confirms every store, including the
/// `0xdeadbabe` guard and the 0x200-byte run-queue clear.
pub unsafe fn init_thread_system() {
    let context = SYSTEM_CONTEXT;
    write_u16(context + 0x2c8, 2);
    write_u16(context + 0x2ca, 1);
    write_u32(context + 0x2d4, 0x10);
    write_u32(context + 0x2d0, 0x10);
    write_u32(context + 0x2cc, 0);
    write_u32(context + 0x2d8, 0xffff_ffff);
    write_u32(context + 0x2e8, 0);
    write_u32(context + 0x2ec, 0);
    write_u32(context + 0x2f0, 0);
    write_u32(context + 0x2f4, 0);
    write_u32(context + 0x2f8, 0);
    write_u32(CURRENT_CONTEXT, context as u32);
    clear_context(context);
    install_context(context);
    write_u32(context + 0x304, 0x8043_fc40);
    write_u32(context + 0x308, 0x8042_fc3c);
    write_u32(0x8042_fc3c, 0xdead_babe);
    let handler = read_u32(sda(SWITCH_HANDLER_OFFSET)) as usize;
    call2(handler, read_u32(CURRENT_THREAD), context as u32);
    write_u32(CURRENT_THREAD, context as u32);
// unknown: `0x801acf10` reads the current stack pointer; its exact SDK
// name is not recovered. The returned value bounds the boot-stack clear.
    let stack_pointer = call0_ret(0x801a_cf10) as usize;
    let mut p = read_u32(CURRENT_THREAD + 0x308) as usize + 4;
    while p < stack_pointer {
        write_u32(p, 0);
        p += 4;
    }
    write_u32(sda(READY_MASK), 0);
    write_u32(sda(RESCHEDULE_FLAG), 0);
    let mut queue = RUN_QUEUE_TABLE;
    for _ in 0..(2 * 0x20) {
        write_u32(queue, 0);
        queue += 4;
    }
    write_u32(ACTIVE_THREAD_HEAD, context as u32);
    write_u32(0x8038_ec34, 0);
    write_u32(0x8038_ec38, 0);
    write_u32(ACTIVE_THREAD_TAIL, context as u32);
    clear_context(IDLE_CONTEXT);
    write_u32(sda(SCHEDULER_LOCK), 0);
}

