// ---------------------------------------------------------------------------
// Power / reset callback chain

// ---------------------------------------------------------------------------
/// Head of the power/reset callback list (`r13 - 0x4f88`).
const POWER_CALLBACK_HEAD: isize = -0x4f88;
/// Tail of the power/reset callback list (`r13 - 0x4f84`).
const POWER_CALLBACK_TAIL: isize = -0x4f84;
/// Callback function (`node + 0x00`).
const POWER_CALLBACK_FN: usize = 0x00;
/// Callback ordering key (`node + 0x04`).
const POWER_CALLBACK_KEY: usize = 0x04;
/// Next callback (`node + 0x08`).
const POWER_CALLBACK_NEXT: usize = 0x08;
/// Previous callback (`node + 0x0c`).
const POWER_CALLBACK_PREV: usize = 0x0c;
/// Inserts a node into the key-sorted power/reset callback list.
///
/// # Original
/// - Ghidra: `FUN_801b32d0` at `0x801b32d0` (136 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801b32d0_FUN_801b32d0.c`: walks the
///   list while `node.key <= new.key`, then relinks `+0x08`/`+0x0c` and
///   updates the head/tail globals.
///
/// # Arguments
/// - `callback`: node to insert; `+0x04` is its ordering key.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// `callback` must be writable and not already linked.
///
/// # Confidence
/// high.
pub unsafe fn insert_power_callback(callback: usize) {
    let key = read_u32(callback + POWER_CALLBACK_KEY);
    let mut cursor = read_u32(sda(POWER_CALLBACK_HEAD)) as usize;
    while cursor != 0 && read_u32(cursor + POWER_CALLBACK_KEY) <= key {
        cursor = read_u32(cursor + POWER_CALLBACK_NEXT) as usize;
    }
    if cursor == 0 {
        let tail = read_u32(sda(POWER_CALLBACK_TAIL)) as usize;
        if tail == 0 {
            write_u32(sda(POWER_CALLBACK_HEAD), callback as u32);
        } else {
            write_u32(tail + POWER_CALLBACK_NEXT, callback as u32);
        }
        write_u32(callback + POWER_CALLBACK_PREV, tail as u32);
        write_u32(callback + POWER_CALLBACK_NEXT, 0);
        write_u32(sda(POWER_CALLBACK_TAIL), callback as u32);
        return;
    }
    write_u32(callback + POWER_CALLBACK_NEXT, cursor as u32);
    let prev = read_u32(cursor + POWER_CALLBACK_PREV) as usize;
    write_u32(cursor + POWER_CALLBACK_PREV, callback as u32);
    write_u32(callback + POWER_CALLBACK_PREV, prev as u32);
    if prev == 0 {
        write_u32(sda(POWER_CALLBACK_HEAD), callback as u32);
    } else {
        write_u32(prev + POWER_CALLBACK_NEXT, callback as u32);
    }
}

/// Runs the power/reset callback chain and reports whether it succeeded.
///
/// # Original
/// - Ghidra: `FUN_801b3360` at `0x801b3360` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801b3360_FUN_801b3360.c`: walks
///   nodes with the same key, calls `node->fn(a, b)`, folds each non-zero
///   result into a flag, then folds in `0x801b4300()`; returns 1 only when
///   every callback and the status read returned 0.
///
/// # Arguments
/// - `a`, `b`: forwarded to every callback.
///
/// # Returns
/// `1` when all callbacks and `0x801b4300` returned 0, otherwise `0`.
///
/// # Safety
/// Every node's function pointer must be callable with `(u32, u32)`.
///
/// # Confidence
/// high for the folding logic; the callback contract is inferred from this
/// call site.
pub unsafe fn run_power_callbacks(a: u32, b: u32) -> u32 {
    let mut any: u32 = 0;
    let mut key: u32 = 0;
    let mut node = read_u32(sda(POWER_CALLBACK_HEAD)) as usize;
    while node != 0 && (any == 0 || key == read_u32(node + POWER_CALLBACK_KEY)) {
        let function = read_u32(node + POWER_CALLBACK_FN) as usize;
        let result = call2(function, a, b);
        any |= result.leading_zeros() >> 5;
        key = read_u32(node + POWER_CALLBACK_KEY);
        node = read_u32(node + POWER_CALLBACK_NEXT) as usize;
    }
    let status = call0_ret(0x801b_4300);
    (any | (status.leading_zeros() >> 5)).leading_zeros() >> 5
}

