// ---------------------------------------------------------------------------
// StateTM register access and shutdown

// ---------------------------------------------------------------------------
/// StateTM register block (base of the six halfword registers at `+0x1c`).
const STM_REGISTERS: usize = 0x8038_e8f4;
/// Non-zero while the StateTM register block is locked.
const STM_REGISTER_LOCK: usize = 0x8038_e928;
/// Interrupt state saved while the register block is locked.
const STM_REGISTER_IRQ: usize = 0x8038_e924;
/// StateTM channel file descriptor (`r13 - 0x4f60`).
const STM_FD: isize = -0x4f60;
/// StateTM initialised flag (`r13 - 0x4f64`).
const STM_READY: isize = -0x4f64;
/// Reads one StateTM halfword register.
///
/// # Original
/// - Ghidra: `FUN_801b4440` at `0x801b4440` (120 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801b4440_FUN_801b4440.c`: takes the
///   register lock at `0x8038e928`, reads the halfword at
///   `0x8038e8f4 + (index + 0xe) * 2`, then calls `0x801b4020(0, 0x14)`.
///
/// # Arguments
/// - `index`: register index 0..5.
///
/// # Returns
/// The halfword register value.
///
/// # Side effects
/// Temporarily publishes/saves the interrupt state in the lock globals.
///
/// # Safety
/// Must run on the target where the StateTM block is mapped; the already-locked
/// path is documented but reads from the low-memory offset, matching the
/// original.
///
/// # Confidence
/// medium - the lock protocol is explicit, the register semantics are not.
pub unsafe fn read_stm_register(index: u32) -> u16 {
    let was_enabled = disable_interrupts();
    let base;
    if read_u32(STM_REGISTER_LOCK) != 0 {
        restore_interrupts(was_enabled);
// observed: the original then uses base 0 and reads low memory at
// 0x1c + index*2; preserved rather than "fixed".
        base = 0usize;
    } else {
        write_u32(STM_REGISTER_IRQ, was_enabled);
        base = STM_REGISTERS;
        write_u32(STM_REGISTER_LOCK, 1);
    }
    let value = read_u16(base + 0x1c + (index as usize) * 2);
    call2(0x801b_4020, 0, 0x14);
    value
}

