pub unsafe fn write_stm_register(index: u32, value: u16) {
    let was_enabled = disable_interrupts();
    let base;
    if read_u32(STM_REGISTER_LOCK) != 0 {
        restore_interrupts(was_enabled);
        base = 0usize;
    } else {
        write_u32(STM_REGISTER_IRQ, was_enabled);
        base = STM_REGISTERS;
        write_u32(STM_REGISTER_LOCK, 1);
    }
    let address = base + 0x1c + (index as usize) * 2;
    if read_u16(address) == value {
        call2(0x801b_4020, 0, 0x14);
    } else {
        write_u16(address, value);
        call2(0x801b_4020, 1, 0x14);
    }
}

