    write_u32(WAVE38_IOS_ZERO, 0);
    write_u8(WAVE38_IOS_MODE, 0xff);
    fn_801b1510(0xf000_0000);
    fn_801b11b0(0, 0x801b_2620);
    fn_801b11b0(1, 0x801b_2620);
    fn_801b11b0(2, 0x801b_2620);
    fn_801b11b0(3, 0x801b_2620);
    fn_801b11b0(4, 0x801b_2620);
