    while cursor != end && read_i32(cursor) != key {
        cursor += 4;
    }
    if cursor == end {
        return 0;
    }
// observed: the export keeps the byte difference then divides it by four.
    let index = ((cursor - base) as u32) >> 2;
    let vtable = read_u32(owner) as usize;
    let remove = read_u32(vtable + 0x38) as usize;
    let result = call2(remove, owner as u32, index);
// observed: (-result | result) >> 31, i.e. 1 when the call returned non-zero.
