        let b_vtable = read_u32(b) as usize;
        let b_reader = read_u32(b_vtable + 0x2c) as usize;
        let b_value = f32::from_bits(call1(b_reader, b as u32)) as f64;
        let a_vtable = read_u32(a) as usize;
