        write_u32(component + 0x24, neutral_bits);
        write_u32(component + 0x2c, neutral_bits);
        write_u32(component + 0x30, scalar_bits);
        write_u32(component + 0x34, neutral_bits);
        write_u32(component + 0x3c, neutral_bits);
        write_u32(component + 0x40, neutral_bits);
        write_u32(component + 0x44, scalar_bits);
