            let sequence = call3(0x8025_1930, key.as_mut_ptr().add(2) as u32, key.as_mut_ptr().add(1) as u32,
                key.as_mut_ptr() as u32, );
            call7(0x8024_e180, key.as_ptr().add(4) as u32, key.as_ptr().add(3) as u32, 0, 0, entry_flags,
                0, sequence, );
