/// the output is the full twelve-float record: the nine cofactors over the
/// determinant at `+0x00`..`+0x20` in the order `C00, C01, C02, C10, ...`,
/// `C22`, and `0.0` at `+0x0C`, `+0x1C` and `+0x2C`. When `out` and `matrix`
/// are the same buffer the singular path writes nothing at all, because the
/// copy it would perform is the identity of the operation.
///
/// # Original
/// - Ghidra: `FUN_80242930` at `0x80242930` (264 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80242930_FUN_80242930.c`
///
/// # Arguments
/// - `out`: twelve writable floats.
/// - `matrix`: the 3x4 source; may alias `out`.
///
/// # Returns
/// `1` when the inverse was written, `0` when the input was singular.
///
/// # Side effects
/// Twelve float stores, or none when the input is singular and aliased.
///
/// # Safety
/// `out` must be writable for `0x30` bytes and `matrix` readable for `0x2C`.
///
/// # Confidence
/// high - the cofactor order, the three zero slots and the
/// `param_1 != param_2` guard are literal; the `GQR` arms are dropped for the
/// reason given in [`fn_80242840`].
pub unsafe fn fn_80242930(out: usize, matrix: usize) -> u32 {
    let c0x = read_f32(matrix);
    let c0y = read_f32(matrix + 4);
    let c0z = read_f32(matrix + 8);
    let c1x = read_f32(matrix + 0x10);
    let c1y = read_f32(matrix + 0x14);
    let c1z = read_f32(matrix + 0x18);
    let c2x = read_f32(matrix + 0x20);
    let c2y = read_f32(matrix + 0x24);
    let c2z = read_f32(matrix + 0x28);
    let cofactor_20 = c0y * c1z - c1y * c0z;
    let cofactor_00 = c1y * c2z - c2y * c1z;
    let cofactor_10 = c2y * c0z - c0y * c2z;
    let det = c2x * cofactor_20 + c1x * cofactor_10 + c0x * cofactor_00;
    let epsilon = read_f32(sda(W100_DET_EPSILON));
    if epsilon <= det.abs() {
        let mut reciprocal = 1.0f32 / det;
        write_f32(out + 0x0c, 0.0);
        write_f32(out + 0x1c, 0.0);
        write_f32(out + 0x2c, 0.0);
        reciprocal = -(reciprocal * det * reciprocal - (reciprocal + reciprocal));
        write_f32(out, cofactor_00 * reciprocal);
        write_f32(out + 4, (c1z * c2x - c2z * c1x) * reciprocal);
        write_f32(out + 8, (c1x * c2y - c1y * c2x) * reciprocal);
        write_f32(out + 0x10, cofactor_10 * reciprocal);
        write_f32(out + 0x14, (c2z * c0x - c0z * c2x) * reciprocal);
        write_f32(out + 0x18, (c0y * c2x - c0x * c2y) * reciprocal);
        write_f32(out + 0x20, cofactor_20 * reciprocal);
        write_f32(out + 0x24, (c0z * c1x - c1z * c0x) * reciprocal);
        write_f32(out + 0x28, (c0x * c1y - c0y * c1x) * reciprocal);
        1
    } else {
        if out != matrix {
            write_f32(out, c0x);
            write_f32(out + 4, c0y);
            write_f32(out + 8, c0z);
            write_f32(out + 0x10, c1x);
            write_f32(out + 0x14, c1y);
            write_f32(out + 0x18, c1z);
            write_f32(out + 0x20, c2x);
            write_f32(out + 0x24, c2y);
            write_f32(out + 0x28, c2z);
            write_f32(out + 0x0c, 0.0);
            write_f32(out + 0x1c, 0.0);
            write_f32(out + 0x2c, 0.0);
        }
        0
    }
}

/// Builds the full affine inverse of a 3x4 matrix.
///
/// Columns at `+0x00`, `+0x10`, `+0x20`, translation at `+0x0C`, `+0x1C`,
/// `+0x2C`. The nine cofactors divided by the determinant land at `+0x00`,
/// `+0x04`, `+0x08` (`C00`, `C10`, `C20`), `+0x10`, `+0x14`, `+0x18`
/// (`C01`, `C11`, `C21`) and `+0x20`, `+0x24`, `+0x28` (`C02`, `C12`, `C22`),
/// which is the inverse laid out row-wise. The three translation slots then
/// receive `-(row . translation)` for the three rows, i.e. `-R^-1 t`.
///
/// # Original
/// - Ghidra: `FUN_80242a40` at `0x80242A40` (260 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80242a40_FUN_80242a40.c`
///
/// # Arguments
/// - `out`: twelve writable floats.
/// - `matrix`: the 3x4 source; may alias `out` (the translation is read before
///   the first store).
///
/// # Returns
/// `1` when the inverse was written, `0` when `|det|` was below the epsilon.
///
/// # Side effects
/// Twelve float stores on the success path, none on the singular path.
///
/// # Safety
/// `out` must be writable for `0x30` bytes and `matrix` readable for `0x2C`.
///
/// # Confidence
/// high - the determinant, the six cofactor sums, the refined reciprocal and
/// every store slot are literal; the `GQR` arms are dropped as in
/// [`fn_80242840`].
pub unsafe fn fn_80242a40(out: usize, matrix: usize) -> u32 {
    let c0x = read_f32(matrix);
    let c0y = read_f32(matrix + 4);
    let c0z = read_f32(matrix + 8);
    let c1x = read_f32(matrix + 0x10);
    let c1y = read_f32(matrix + 0x14);
    let c1z = read_f32(matrix + 0x18);
    let c2x = read_f32(matrix + 0x20);
    let c2y = read_f32(matrix + 0x24);
    let c2z = read_f32(matrix + 0x28);
    let cofactor_20 = c0y * c1z - c1y * c0z;
    let cofactor_00 = c1y * c2z - c2y * c1z;
    let cofactor_10 = c2y * c0z - c0y * c2z;
    let det = c2x * cofactor_20 + c1x * cofactor_10 + c0x * cofactor_00;
    let epsilon = read_f32(sda(W100_DET_EPSILON));
    if epsilon <= det.abs() {
        let mut reciprocal = 1.0f32 / det;
        reciprocal = -(reciprocal * det * reciprocal - (reciprocal + reciprocal));
        let tx = read_f32(matrix + 0x0c);
        let ty = read_f32(matrix + 0x1c);
        let tz = read_f32(matrix + 0x2c);
        let inv_00 = cofactor_00 * reciprocal;
        let inv_10 = cofactor_10 * reciprocal;
        let inv_20 = cofactor_20 * reciprocal;
        let inv_01 = (c1z * c2x - c2z * c1x) * reciprocal;
        let inv_11 = (c2z * c0x - c0z * c2x) * reciprocal;
        let inv_21 = (c0z * c1x - c1z * c0x) * reciprocal;
        let inv_02 = (c1x * c2y - c1y * c2x) * reciprocal;
        let inv_12 = (c0y * c2x - c0x * c2y) * reciprocal;
        let inv_22 = (c0x * c1y - c0y * c1x) * reciprocal;
        write_f32(out, inv_00);
        write_f32(out + 4, inv_10);
        write_f32(out + 8, inv_20);
        write_f32(out + 0x10, inv_01);
        write_f32(out + 0x14, inv_11);
        write_f32(out + 0x18, inv_21);
        write_f32(out + 0x20, inv_02);
        write_f32(out + 0x24, inv_12);
        write_f32(out + 0x28, inv_22);
        write_f32(out + 0x0c, -(inv_00 * tx + inv_10 * ty + inv_20 * tz));
        write_f32(out + 0x1c, -(inv_01 * tx + inv_11 * ty + inv_21 * tz));
        write_f32(out + 0x2c, -(inv_02 * tx + inv_12 * ty + inv_22 * tz));
        1
    } else {
        0
    }
}

