    let mut cursor = text;
    let mut font = 0u32;
// `code` starts as the raw byte of modes 0/1 so the allocator still gets
// the decoded value when the character never reaches `0x8038FA68`-style
// remapping.
    let mut value = 0u32;
// `flag` is the export's `iVar7`: the mode until the remap branch runs.
    let mut flag = mode;
