    const HOT_RESET_FAILED: u32 = 0x8033_3b04;
    // "OSReturnToMenu: Falied to bo..."
    const MENU_FAILED: u32 = 0x8033_3b30;
    let mut menu = [0u8; 8];
    let mut alt = [0u8; 8];
    let mut alt2 = [0u8; 8];
    let mut status = [0i32; 1];
    call0(0x801b_7280);
    call0(0x801b_6b40);
    call0(0x801c_f8f0);
    call1(0x801b_7560, menu.as_mut_ptr() as u32);
