        alt2[6] = 2;
        alt2[5] = 3;
        call0(0x801b_4680);
        call1(0x801b_7470, alt2.as_mut_ptr() as u32);
        wave102_power_down(OS_RESET_C, HOT_RESET_FAILED, MENU_FAILED);
