    write_u32(sda(-0x4ea4), 0);
    write_u32(sda(-0x4ea0), 0);
    write_u32(sda(-0x4e28), 0);
    write_u32(sda(-0x4eb4), 1);
    write_u32(sda(-0x4e9c), 0);
