/// Publishes one pending scan-out field.
///
/// Every producer in this section writes one halfword of `0x8038FA68` and then
/// touches the two pending words: a read/write of `sda(-0x4E84)` (the export's
/// barrier between two stores) and an OR of one bit into `sda(-0x4E88)`. The
/// bit is the field's index counted from the top of the high word, which is
/// exactly what the `count_leading_zeros` drain in [`fn_801bdcb0`] walks.
///
/// # Original
/// - Not an original function: the repeated three-instruction publish sequence
///   (`lwz`/`stw` of `sda(-0x4E84)`, then `ori` into `sda(-0x4E88)`).
///
/// # Arguments
/// - `bit`: the pending bit of the field just stored.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// Both words must be readable and writable.
///
/// # Confidence
/// high - the sequence is identical in all four producers.
#[inline]unsafe fn wave102_publish(bit: u32) {
    write_u32(sda(W102_VI_PENDING_LO), read_u32(sda(W102_VI_PENDING_LO)));
    write_u32(sda(W102_VI_PENDING_HI), read_u32(sda(W102_VI_PENDING_HI)) | bit, );
}

/// Calls a nine-argument function.
///
/// # Original
/// - Not an original function: host-side helper for `0x801BD0E0`, the only
///   nine-argument callee in this section.
///
/// # Safety
/// `addr` must be callable with nine word arguments.
#[inline]unsafe fn wave102_call9(addr: usize, a: u32, b: u32, c: u32, d: u32, e: u32, f: u32,
    g: u32, h: u32, i: u32,) -> u32 {
    let fp: extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32, u32) -> u32 = core::mem::transmute(addr);
    fp(a, b, c, d, e, f, g, h, i)
}

/// Calls a four-argument function that returns a 64-bit value.
///
/// # Original
/// - Not an original function: host-side helper for `0x802DCEC4`, the 64-bit
///   remainder helper whose four arguments are the dividend's high and low
///   words, a zero and the divisor.
///
/// # Safety
/// `addr` must be callable with `(high, low, zero, divisor)`.
#[inline]unsafe fn wave102_mod64(addr: usize, high: u32, low: u32, divisor: u32) -> u64 {
    let fp: extern "C" fn(u32, u32, u32, u32) -> u64 = core::mem::transmute(addr);
    fp(high, low, 0, divisor)
}

/// Recomputes the four `XFB` addresses of the scan window.
///
/// `0x8038FAE0` is a `0x34`-byte window descriptor: `+0x00` the visible
/// height, `+0x02` the field stride, `+0x04` the line length, `+0x06` the
/// frame height, `+0x08` the letterbox height, `+0x0A` the interlace flag,
/// `+0x20` the "second field" flag, `+0x30`/`+0x48` the two frame bases and
/// `+0x3C` the format byte. The two base words are computed as
/// `stride * +0x0E + base + (word at +0x16 & 0x7FFFFFF0) * 2`, optionally
/// swapped when bit 0 of `+0x0A` is set, masked to the `0x3FFFFFFF` address
/// range, and scaled down by 5 when any of the four exceeds `0x1000000`
/// (i.e. when the addresses are not in MEM1 and need the `>>5` form the
/// video interface expects).
///
/// # Original
/// - Ghidra: `FUN_801bcd50` at `0x801bcd50` (680 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801bcd50_FUN_801bcd50.c`
///
/// # Arguments
/// - `window`: the `0x8038FAE0` descriptor.
/// - `top_left`, `bottom_left`, `top_right`, `bottom_right`: the four output
///   words; the first pair is always written, the second only when
///   `window + 0x44` is set.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Eight VI halfwords in `0x8038FA68` and eight pending bits.
///
/// # Safety
/// All five pointers must be word-aligned and writable.
///
/// # Confidence
/// medium - the arithmetic, the swap and the `>>5` rule are literal; the field
/// names are `// inferred:` from how [`fn_801bdcb0`] uploads them.
pub unsafe fn fn_801bcd50(window: usize, top_left: usize, bottom_left: usize, top_right: usize,
    bottom_right: usize,) {
    let stride = read_u8(window + 0x2c) as u32 * 0x20;
    let second_field = read_u32(window + 0x20);
    let interlace = read_u16(window + 0x0a);
    let mut address = stride * read_u16(window + 0x0e) as u32 + read_u32(window + 0x30) + (read_u16(window + 0x16) as u32 & 0x7fff_fff0) * 2;
    write_u32(top_left, address);
    if second_field != 0 {
        address = address.wrapping_add(stride);
    }
    write_u32(bottom_left, address);
    if interlace & 1 == 1 {
        let swap = read_u32(top_left);
        write_u32(top_left, address);
        write_u32(bottom_left, swap);
    }
    write_u32(top_left, read_u32(top_left) & 0x3fff_ffff);
    write_u32(bottom_left, read_u32(bottom_left) & 0x3fff_ffff);
    if read_u32(window + 0x44) != 0 {
        let mut alternate = stride * read_u16(window + 0x0e) as u32 + read_u32(window + 0x48) + (read_u16(window + 0x16) as u32 & 0x7fff_fff0) * 2;
        write_u32(top_right, alternate);
        if second_field != 0 {
            alternate = alternate.wrapping_add(stride);
        }
        write_u32(bottom_right, alternate);
        if interlace & 1 == 1 {
            let swap = read_u32(top_right);
            write_u32(top_right, alternate);
            write_u32(bottom_right, swap);
        }
        write_u32(top_right, read_u32(top_right) & 0x3fff_ffff);
        write_u32(bottom_right, read_u32(bottom_right) & 0x3fff_ffff);
    }
    let scaled = read_u32(top_left) >= 0x0100_0000 || read_u32(bottom_left) >= 0x0100_0000 || read_u32(top_right) >= 0x0100_0000 || read_u32(bottom_right) >= 0x0100_0000;
    if scaled {
        write_u32(top_left, read_u32(top_left) >> 5);
        write_u32(bottom_left, read_u32(bottom_left) >> 5);
        write_u32(top_right, read_u32(top_right) >> 5);
        write_u32(bottom_right, read_u32(bottom_right) >> 5);
    }
    let left = read_u32(top_left);
    write_u16(0x8038_fa86, left as u16);
    wave102_publish(0x0001_0000);
    let format_byte = read_u8(window + 0x3c) as u16;
    write_u16(0x8038_fa84, (scaled as u16) << 0x0c | (left >> 0x10) as u16 | format_byte << 8,
        );
    wave102_publish(0x0002_0000);
    let left_bottom = read_u32(bottom_left);
    write_u16(0x8038_fa8e, left_bottom as u16);
    write_u16(0x8038_fa8c, (left_bottom >> 0x10) as u16);
    wave102_publish(0x0000_1000);
    wave102_publish(0x0000_2000);
    if read_u32(window + 0x44) != 0 {
        let right = read_u32(top_right);
        write_u16(0x8038_fa88, (right >> 0x10) as u16);
        wave102_publish(0x0000_4000);
        write_u16(0x8038_fa8a, right as u16);
        wave102_publish(0x0000_8000);
        let right_bottom = read_u32(bottom_right);
        write_u16(0x8038_fa92, right_bottom as u16);
        write_u16(0x8038_fa90, (right_bottom >> 0x10) as u16);
        wave102_publish(0x0000_0400);
        wave102_publish(0x0000_0800);
    }
}

/// Sets the two scan-out window halves and the frame height.
///
/// Stores the record's line count (`+0x1A`) and its `+0x1D` timing word, then
/// the two active-window words: when the TV format is `8` (a VGA mode) the
/// window is the record's `+0x1F` byte plus `0xAC` by its `+0x20` word;
/// otherwise it is the visible origin plus or minus `0x28` lines, capped by
/// `0x2D0 - height`. The four results become `0x8038FA70`/`0x8038FA72`.
///
/// # Original
/// - Ghidra: `FUN_801bd000` at `0x801bd000` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801bd000_FUN_801bd000.c`
///
/// # Arguments
/// - `record`: the TV-format record from [`fn_801bc480`].
/// - `origin`: the current visible origin (`0x8038FAE8`).
/// - `height`: the visible height; `// unknown:` the only caller passes two
///   arguments, so this arrives in the still-live `r5`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Four VI halfwords and four pending bits.
///
/// # Safety
/// `record` must be a readable `0x26`-byte record.
///
/// # Confidence
/// low - the two branches and the four stores are literal, but the third
/// argument is never set by `0x801BD280`, so `0x2D0 - height` cannot be
/// verified.
pub unsafe fn fn_801bd000(record: usize, origin: u32, height: u32) {
    let format = read_u32(0x8038_fb08);
    write_u16(0x8038_fa6e, read_u16(record + 0x1a));
    wave102_publish(0x1000_0000);
    write_u16(0x8038_fa6c, read_u16(record + 0x1d));
    wave102_publish(0x2000_0000);
    let (mut top, mut bottom);
    if format == 8 {
        bottom = read_u16(record + 0x20) as u32;
        top = read_u8(record + 0x1f) as u32 + 0xac;
    } else {
        top = origin.wrapping_add(read_u8(record + 0x1f) as u32).wrapping_sub(0x28);
        bottom = origin .wrapping_add(read_u16(record + 0x20) as u32) .wrapping_add(0x28) .wrapping_sub(0x2d0u32.wrapping_sub(height));
    }
    let format_byte = read_u8(record + 0x1c) as u16;
    write_u16(0x8038_fa72, format_byte | (top << 7) as u16);
    wave102_publish(0x0400_0000);
    write_u16(0x8038_fa70, (top >> 9) as u16 | (bottom << 1) as u16);
    wave102_publish(0x0800_0000);
}

/// Positions the four scan-out corners of one field.
///
/// `0x8038FB04` is the field selector: `2`/`3` (the interlaced field pairs)
/// use multiplier `1` and sign `2`, every other value the opposite. The four
/// corner words are `left/right + sign * (multiplier * top - origin - phase)`
/// and `top/bottom + sign * phase`; bit 0 of the phase selects which pair is
/// which. When `mirror` (the caller's `0x8038FB20`) is set the whole quad is
/// shifted by two lines and the phase word is zeroed, which is what the
/// alternating field needs.
///
/// # Original
/// - Ghidra: `FUN_801bd0e0` at `0x801bd0e0` (404 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801bd0e0_FUN_801bd0e0.c`
///
/// # Arguments
/// - `phase`: `0x8038FAEA` (the current letterbox phase).
/// - `origin`: `0x8038FAEC` (the current visible origin).
/// - `format`: the record's `+0x00` word.
/// - `top`, `right`, `bottom`, `left`: the record's `+0x02`..`+0x0A` corner
///   words, in the export's order.
/// - `alternate`: the record's `+0x0A` word.
/// - `mirror`: `0x8038FB20`, non-zero on the alternating field.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Five VI halfwords and five pending bits.
///
/// # Safety
/// None beyond the SDA words being live.
///
/// # Confidence
/// medium - the sign ladder, the `i16` truncation and the five pending bits are
/// literal; `// inferred:` the corner role names from the record layout.
pub unsafe fn fn_801bd0e0(phase: u32, origin: i32, format: u16, top: i16, right: i16, bottom: i16,
    left: i16, alternate: i16, mirror: i32,) {
    let (multiplier, sign) = if read_u32(0x8038_fb04).wrapping_sub(2) < 2 {
        (1i16, 2i16)
    } else {
        (2i16, 1i16)
    };
    let phase16 = phase as u16 as i16;
    let step = (multiplier as i32 * top as i32 - origin - phase16 as i32) as i16;
    let offset = sign.wrapping_mul(step);
    let shift = sign.wrapping_mul(phase16);
    if phase & 1 == 0 {
        write_u16(0x8038_fa74, left.wrapping_add(offset) as u16);
        write_u16(0x8038_fa76, right.wrapping_add(shift) as u16);
        write_u16(0x8038_fa78, alternate.wrapping_add(offset) as u16);
        write_u16(0x8038_fa7a, bottom.wrapping_add(shift) as u16);
    } else {
        write_u16(0x8038_fa74, alternate.wrapping_add(offset) as u16);
        write_u16(0x8038_fa76, bottom.wrapping_add(shift) as u16);
        write_u16(0x8038_fa7a, right.wrapping_add(shift) as u16);
        write_u16(0x8038_fa78, left.wrapping_add(offset) as u16);
    }
    let mut phase_scale = (origin / multiplier as i32) as u32 & 0xffff;
    if mirror != 0 {
        write_u16(0x8038_fa74, read_u16(0x8038_fa74).wrapping_add(2));
        let trim = (origin / multiplier as i32) as i16 * 2 - 2;
        phase_scale = 0;
        write_u16(0x8038_fa78, read_u16(0x8038_fa78).wrapping_add(2));
        write_u16(0x8038_fa76, read_u16(0x8038_fa76).wrapping_add(trim as u16));
        write_u16(0x8038_fa7a, read_u16(0x8038_fa7a).wrapping_add(trim as u16));
    }
    wave102_publish(0x8000_0000);
    write_u16(0x8038_fa68, format | (phase_scale << 4) as u16);
    wave102_publish(0x0100_0000);
    wave102_publish(0x0200_0000);
    wave102_publish(0x0040_0000);
    wave102_publish(0x0080_0000);
}

