            call3(0x8023_d460, at(0x5c) as u32, 0, at(0x70) as u32);
            call3(0x8023_d460, at(0x5c) as u32, 1, at(0x6c) as u32);
            call3(0x8023_d460, at(0x5c) as u32, 2, at(0x68) as u32);

