/// # Confidence
/// high - the five literal records and the final `subf`/`cntlzw` equality
/// test are explicit.
pub unsafe fn fn_8025ebb0(_this: usize, other: usize) -> u32 {
    let kind = read_u32(other);
    if kind == W285_SCNMDL_TYPE as u32
        || kind == W285_SCNMDL_SIMPLE_TYPE as u32
        || kind == W285_SCNLEAF_TYPE as u32
        || kind == W285_SCNOBJ_TYPE as u32
    {
        return 1;
    }
    (W285_G3DOBJ_TYPE as u32).wrapping_sub(kind).leading_zeros() >> 5
}

